<?php
declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/helpers.php';exigirAdmin();
$registros=db()->query("SELECT a.*,ua.nome ator,ue.nome efetivo FROM auditoria a LEFT JOIN usuarios ua ON ua.id=a.usuario_id LEFT JOIN usuarios ue ON ue.id=a.usuario_efetivo_id ORDER BY a.id DESC LIMIT 500")->fetch_all(MYSQLI_ASSOC);$titulo='Auditoria';require __DIR__.'/includes/header.php';?>
<section class="page-head"><div><h1>Auditoria</h1><p>Últimas 500 ações relevantes realizadas no sistema.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Autor real</th><th>Conta utilizada</th><th>Ação</th><th>Registro</th><th>IP</th><th>Detalhes</th></tr></thead><tbody><?php if(!$registros):?><tr><td colspan="7" class="empty">Nenhuma ação registrada.</td></tr><?php endif;?><?php foreach($registros as $r):?><tr><td class="cell-nowrap"><?=e($r['criado_em'])?></td><td><?=e($r['ator']?:'Sistema/visitante')?></td><td><?=e($r['efetivo']?:'-')?></td><td><strong><?=e($r['acao'])?></strong></td><td><?=e(($r['entidade']?:'-').($r['entidade_id']?' #'.$r['entidade_id']:''))?></td><td><?=e($r['ip']?:'-')?></td><td class="notes-cell"><?=e($r['detalhes']?:'-')?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php';?>
